/**
 * Generates authoritative Chronicle/LZ4 persistence fixtures through the real
 * {@link DiskSerializationProcessor}. The generated bytes are intentionally
 * opaque to this test: two independent exchange runs must produce identical
 * files before anything is published into {@code src/zig/fixtures}.
 */
public final class GenerateJavaPersistenceFixtureTest {

    private static final String WRITE_PROPERTY = "java.persistence.fixture.write";
    private static final String OUTPUT_PROPERTY = "java.persistence.fixture.path";
    private static final String DEFAULT_OUTPUT_PATH = "src/zig/fixtures/java-persistence/v1";

    private static final String EXCHANGE_ID = "JAVAPERSISTV1";
    private static final long SNAPSHOT_ID = 4_242_424_242L;
    private static final long BASE_TIMESTAMP_NS = 1_700_000_000_000_000_000L;

    private static final int MATCHING_ENGINES = 1;
    private static final int RISK_ENGINES = 1;
    private static final int SYMBOL = 5_991;
    private static final int BASE_CURRENCY = 840;
    private static final int QUOTE_CURRENCY = 392;
    private static final long MAKER_UID = 7_001L;
    private static final long TAKER_UID = 7_002L;
    private static final long MAKER_ORDER_ID = 101L;
    private static final long TAKER_ORDER_ID = 102L;
    private static final long JOURNAL_ORDER_ID = 103L;
    private static final long MAKER_INITIAL_BALANCE = 240_000L;
    private static final long TAKER_INITIAL_BALANCE = 150_000L;
    private static final long JOURNAL_BALANCE_DELTA = 12_345L;

    private static final long COMMAND_SETTLE_DELAY_MS = 20L;
    private static final long FUTURE_TIMEOUT_SECONDS = 10L;
    private static final int JOURNAL_RAW_THRESHOLD = Integer.MAX_VALUE;

    private static final CoreSymbolSpecification SYMBOL_SPEC = CoreSymbolSpecification.builder()
            .symbolId(SYMBOL)
            .type(SymbolType.FUTURES_CONTRACT)
            .baseCurrency(BASE_CURRENCY)
            .quoteCurrency(QUOTE_CURRENCY)
            .baseScaleK(100_000L)
            .quoteScaleK(10L)
            .marginBuy(5_000L)
            .marginSell(6_000L)
            .takerFee(3L)
            .makerFee(2L)
            .build();

    @Test
    public void writeDeterministicDiskPersistenceFixture() throws Exception {
        assumeTrue(Boolean.getBoolean(WRITE_PROPERTY), "manual persistence fixture generation only");

        final Path targetRoot = Paths.get(System.getProperty(OUTPUT_PROPERTY, DEFAULT_OUTPUT_PATH));
        final Path temporaryRoot = Paths.get("target");
        Files.createDirectories(temporaryRoot);

        final Path firstWorkDir = Files.createTempDirectory(temporaryRoot, "java-persistence-fixture-a-");
        final Path secondWorkDir = Files.createTempDirectory(temporaryRoot, "java-persistence-fixture-b-");

        try {
            final GenerationResult first = generateAndVerify(firstWorkDir);
            final GenerationResult second = generateAndVerify(secondWorkDir);

            assertEquals(first.snapshotSequenceMatching, second.snapshotSequenceMatching,
                    "matching snapshot sequence changed across identical runs");
            assertEquals(first.snapshotSequenceRisk, second.snapshotSequenceRisk,
                    "risk snapshot sequence changed across identical runs");
            assertEquals(first.journalBalanceSequence, second.journalBalanceSequence,
                    "journal balance sequence changed across identical runs");
            assertEquals(first.journalOrderSequence, second.journalOrderSequence,
                    "journal order sequence changed across identical runs");
            assertEquals(first.snapshotState, second.snapshotState,
                    "snapshot business state changed across identical runs");
            assertEquals(first.journalState, second.journalState,
                    "post-journal business state changed across identical runs");

            for (String fileName : sourceArtifactNames()) {
                assertArrayEquals(
                        Files.readAllBytes(first.workDir.resolve(fileName)),
                        Files.readAllBytes(second.workDir.resolve(fileName)),
                        "persistence bytes changed across identical runs for " + fileName);
            }

            publishFixture(first, targetRoot);
        } finally {
            deleteWorkingDirectory(firstWorkDir);
            deleteWorkingDirectory(secondWorkDir);
        }
    }

    private static GenerationResult generateAndVerify(final Path workDir) throws Exception {
        final PerformanceConfiguration performanceConfiguration = performanceConfiguration();
        final SerializationConfiguration journalingConfiguration = serializationConfiguration(workDir, true);
        final AtomicLong matchingSnapshotSequence = new AtomicLong(-1L);
        final AtomicLong riskSnapshotSequence = new AtomicLong(-1L);
        final AtomicLong journalBalanceSequence = new AtomicLong(-1L);
        final AtomicLong journalOrderSequence = new AtomicLong(-1L);
        final AtomicLong journalGroupingEnableSequence = new AtomicLong(-1L);

        final BusinessState snapshotState;
        final BusinessState journalState;

        try (ExchangeTestContainer container = ExchangeTestContainer.create(
                performanceConfiguration,
                InitialStateConfiguration.cleanStartJournaling(EXCHANGE_ID),
                journalingConfiguration)) {

            container.setConsumer((command, sequence) -> {
                if (command.command == OrderCommandType.PERSIST_STATE_MATCHING) {
                    matchingSnapshotSequence.set(sequence);
                } else if (command.command == OrderCommandType.PERSIST_STATE_RISK) {
                    riskSnapshotSequence.set(sequence);
                } else if (command.command == OrderCommandType.BALANCE_ADJUSTMENT
                        && command.orderId == 3L) {
                    journalBalanceSequence.set(sequence);
                } else if (command.command == OrderCommandType.PLACE_ORDER
                        && command.orderId == JOURNAL_ORDER_ID) {
                    journalOrderSequence.set(sequence);
                } else if (command.command == OrderCommandType.GROUPING_CONTROL
                        && command.orderId == 1L) {
                    journalGroupingEnableSequence.set(sequence);
                }
            });

            final ExchangeApi api = container.getApi();
            submitSymbol(api);
            submit(api, command(ApiAddUser.builder().uid(MAKER_UID).build(), 2), CommandResultCode.SUCCESS);
            submit(api, command(ApiAddUser.builder().uid(TAKER_UID).build(), 3), CommandResultCode.SUCCESS);
            submit(api, command(ApiAdjustUserBalance.builder()
                    .uid(MAKER_UID)
                    .transactionId(1L)
                    .currency(QUOTE_CURRENCY)
                    .amount(MAKER_INITIAL_BALANCE)
                    .build(), 4), CommandResultCode.SUCCESS);
            submit(api, command(ApiAdjustUserBalance.builder()
                    .uid(TAKER_UID)
                    .transactionId(2L)
                    .currency(QUOTE_CURRENCY)
                    .amount(TAKER_INITIAL_BALANCE)
                    .build(), 5), CommandResultCode.SUCCESS);

            submit(api, command(ApiPlaceOrder.builder()
                    .uid(MAKER_UID)
                    .orderId(MAKER_ORDER_ID)
                    .price(10_770L)
                    .reservePrice(0L)
                    .size(40L)
                    .action(OrderAction.ASK)
                    .orderType(OrderType.GTC)
                    .symbol(SYMBOL)
                    .userCookie(701)
                    .build(), 6), CommandResultCode.SUCCESS);
            submit(api, command(ApiPlaceOrder.builder()
                    .uid(TAKER_UID)
                    .orderId(TAKER_ORDER_ID)
                    .price(10_770L)
                    .reservePrice(10_770L)
                    .size(30L)
                    .action(OrderAction.BID)
                    .orderType(OrderType.IOC)
                    .symbol(SYMBOL)
                    .userCookie(702)
                    .build(), 7), CommandResultCode.SUCCESS);

            submitIncompleteBinaryTransfer(api);
            submit(api, command(ApiNop.builder().build(), 9), CommandResultCode.SUCCESS);
            snapshotState = captureBusinessState(container, 10_000);

            final ApiPersistState persistState = ApiPersistState.builder().dumpId(SNAPSHOT_ID).build();
            persistState.timestamp = timestamp(20);
            settleGroupingClock();
            assertEquals(
                    CommandResultCode.SUCCESS,
                    api.submitCommandAsync(persistState).get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
                    "snapshot command failed");
            assertTrue(matchingSnapshotSequence.get() >= 0L, "matching snapshot sequence was not observed");
            assertTrue(riskSnapshotSequence.get() > matchingSnapshotSequence.get(),
                    "risk snapshot must follow matching snapshot");

            // GroupingProcessor normally derives serviceFlags/eventsGroup from wall clock.
            // Freeze it around the journal suffix and use the explicit low-level API so
            // the encoded records are identical across independent generator runs.
            api.groupingControl(timestamp(21), 0);
            api.balanceAdjustment(
                    0,
                    0L,
                    timestamp(22),
                    MAKER_UID,
                    3L,
                    QUOTE_CURRENCY,
                    JOURNAL_BALANCE_DELTA,
                    BalanceAdjustmentType.ADJUSTMENT);
            api.placeNewOrder(
                    0,
                    0L,
                    timestamp(23),
                    JOURNAL_ORDER_ID,
                    703,
                    10_600L,
                    10_600L,
                    5L,
                    OrderAction.BID,
                    OrderType.GTC,
                    SYMBOL,
                    TAKER_UID);
            api.groupingControl(timestamp(24), 1);
            submit(api, command(ApiNop.builder().build(), 25), CommandResultCode.SUCCESS);
            journalState = captureBusinessState(container, 20_000);
        }

        // ResultsHandler deliberately suppresses callbacks while GROUPING_CONTROL
        // mode is zero. The two low-level journal commands are adjacent to the
        // observable re-enable barrier, so recover their exact ring sequences
        // without changing the deterministic grouping fields written to disk.
        assertTrue(journalGroupingEnableSequence.get() >= 2L,
                "journal grouping re-enable sequence was not observed");
        journalBalanceSequence.compareAndSet(-1L, journalGroupingEnableSequence.get() - 2L);
        journalOrderSequence.compareAndSet(-1L, journalGroupingEnableSequence.get() - 1L);

        final GenerationResult generated = new GenerationResult(
                workDir,
                matchingSnapshotSequence.get(),
                riskSnapshotSequence.get(),
                journalBalanceSequence.get(),
                journalOrderSequence.get(),
                snapshotState,
                journalState);
        assertTrue(generated.journalBalanceSequence > generated.snapshotSequenceRisk,
                "journal balance sequence must follow the snapshot boundary");
        assertTrue(generated.journalOrderSequence > generated.journalBalanceSequence,
                "journal order sequence must follow the balance adjustment");
        generated.assertArtifactsExist();

        final BusinessState restoredSnapshot = captureRestoredState(
                performanceConfiguration,
                serializationConfiguration(workDir, false),
                InitialStateConfiguration.fromSnapshotOnly(
                        EXCHANGE_ID,
                        SNAPSHOT_ID,
                        generated.snapshotSequenceRisk),
                30_000);
        assertEquals(snapshotState, restoredSnapshot, "snapshot-only restore changed business state");

        final BusinessState restoredJournal = captureRestoredState(
                performanceConfiguration,
                serializationConfiguration(workDir, false),
                InitialStateConfiguration.lastKnownStateFromJournal(
                        EXCHANGE_ID,
                        SNAPSHOT_ID,
                        generated.snapshotSequenceRisk),
                40_000);
        assertEquals(journalState, restoredJournal, "snapshot+journal restore changed business state");

        return generated;
    }

    private static BusinessState captureRestoredState(
            final PerformanceConfiguration performanceConfiguration,
            final SerializationConfiguration serializationConfiguration,
            final InitialStateConfiguration initialStateConfiguration,
            final int transferBase) throws Exception {

        try (ExchangeTestContainer restored = ExchangeTestContainer.create(
                performanceConfiguration,
                initialStateConfiguration,
                serializationConfiguration)) {
            return captureBusinessState(restored, transferBase);
        }
    }

    private static PerformanceConfiguration performanceConfiguration() {
        return PerformanceConfiguration.baseBuilder()
                .matchingEnginesNum(MATCHING_ENGINES)
                .riskEnginesNum(RISK_ENGINES)
                .sendL2ForEveryCmd(true)
                .orderBookFactory(OrderBookDirectImpl::new)
                .build();
    }

    private static SerializationConfiguration serializationConfiguration(
            final Path storageFolder,
            final boolean enableJournaling) {

        final DiskSerializationProcessorConfiguration diskConfiguration =
                DiskSerializationProcessorConfiguration.builder()
                        .storageFolder(storageFolder.toString())
                        .snapshotLz4CompressorFactory(() -> LZ4Factory.safeInstance().fastCompressor())
                        .journalFileMaxSize(4_000L * 1024L * 1024L)
                        .journalBufferSize(256 * 1024)
                        .journalBatchCompressThreshold(JOURNAL_RAW_THRESHOLD)
                        .journalLz4CompressorFactory(() -> LZ4Factory.safeInstance().fastCompressor())
                        .build();

        return SerializationConfiguration.builder()
                .enableJournaling(enableJournaling)
                .serializationProcessorFactory(configuration ->
                        new DiskSerializationProcessor(configuration, diskConfiguration))
                .build();
    }

    private static void submitSymbol(final ExchangeApi api) throws Exception {
        settleGroupingClock();
        assertEquals(
                CommandResultCode.SUCCESS,
                api.submitBinaryCommandAsync(
                                new BatchAddSymbolsCommand(SYMBOL_SPEC),
                                9_001,
                                command -> command.resultCode)
                        .get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
                "symbol registration failed");
    }

    private static void submitIncompleteBinaryTransfer(final ExchangeApi api) throws Exception {
        settleGroupingClock();
        final long encodedLengthWord = 40L << 32;
        api.binaryData(
                0,
                77L,
                timestamp(8),
                (byte) 0,
                encodedLengthWord,
                0x1111_1111_1111_1111L,
                0x2222_2222_2222_2222L,
                0x3333_3333_3333_3333L,
                0x4444_4444_4444_4444L);
    }

    private static <T extends ApiCommand> T command(final T command, final int timestampOffset) {
        command.timestamp = timestamp(timestampOffset);
        return command;
    }

    private static void submit(
            final ExchangeApi api,
            final ApiCommand command,
            final CommandResultCode expectedResult) throws Exception {

        settleGroupingClock();
        assertEquals(
                expectedResult,
                api.submitCommandAsync(command).get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
                "unexpected result for " + command);
    }

    private static void settleGroupingClock() throws InterruptedException {
        Thread.sleep(COMMAND_SETTLE_DELAY_MS);
    }

    private static long timestamp(final int offset) {
        return BASE_TIMESTAMP_NS + offset;
    }

    private static BusinessState captureBusinessState(
            final ExchangeTestContainer container,
            final int transferBase) throws Exception {

        // Journal replay publishes commands before the live Disruptor starts.
        // Establish an ordinary pipeline barrier before reading engine-owned
        // structures directly; report futures below are too late to protect the
        // L2 snapshot captured at the start of this method.
        final ExchangeApi api = container.getApi();
        submit(api, command(ApiNop.builder().build(), transferBase), CommandResultCode.SUCCESS);

        final ExchangeCore core = container.getExchangeCore();
        final MatchingEngineRouter matching = core.getMatchingEngines().get(0);
        final RiskEngine risk = core.getRiskEngines().get(0);
        assertNotNull(matching, "missing matching engine 0");
        assertNotNull(risk, "missing risk engine 0");

        final IOrderBook orderBook = matching.getOrderBooks().get(SYMBOL);
        assertNotNull(orderBook, "missing direct order book");
        final L2MarketData l2 = orderBook.getL2MarketDataSnapshot();

        final SingleUserReportResult maker = api.processReport(
                        new SingleUserReportQuery(MAKER_UID),
                        transferBase + 1)
                .get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
        final SingleUserReportResult taker = api.processReport(
                        new SingleUserReportQuery(TAKER_UID),
                        transferBase + 2)
                .get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
        final TotalCurrencyBalanceReportResult totals = api.processReport(
                        new TotalCurrencyBalanceReportQuery(),
                        transferBase + 3)
                .get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
        final int javaStateHash = api.processReport(
                        new StateHashReportQuery(),
                        transferBase + 4)
                .get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS)
                .getStateHash();

        final RiskEngine.LastPriceCacheRecord lastPrice = risk.getLastPriceCache().get(SYMBOL);
        assertNotNull(lastPrice, "last-price cache was not populated");

        final SortedMap<String, String> fields = new TreeMap<>();
        // State hashes are checked for snapshot/journal round-trip equivalence
        // inside this JVM through BusinessState.javaStateHash. Do not publish
        // component hashes in the portable manifest: order/action/status and
        // processor object identity values are deliberately process-local.
        put(fields, "risk.adjustments.quote", risk.getAdjustments().get(QUOTE_CURRENCY));
        put(fields, "risk.fees.quote", risk.getFees().get(QUOTE_CURRENCY));
        put(fields, "risk.last_price.ask", lastPrice.askPrice);
        put(fields, "risk.last_price.bid", lastPrice.bidPrice);
        put(fields, "risk.suspends.quote", risk.getSuspends().get(QUOTE_CURRENCY));
        put(fields, "totals.accounts.quote", totals.getAccountBalances().get(QUOTE_CURRENCY));
        put(fields, "totals.adjustments.quote", totals.getAdjustments().get(QUOTE_CURRENCY));
        put(fields, "totals.fees.quote", totals.getFees().get(QUOTE_CURRENCY));
        put(fields, "totals.open_interest.long", totals.getOpenInterestLong().get(SYMBOL));
        put(fields, "totals.open_interest.short", totals.getOpenInterestShort().get(SYMBOL));
        put(fields, "totals.orders.quote", totals.getOrdersBalances().get(QUOTE_CURRENCY));

        putL2(fields, l2);
        putUser(fields, "maker", maker, MAKER_ORDER_ID);
        putUser(fields, "taker", taker, JOURNAL_ORDER_ID);

        return new BusinessState(javaStateHash, fields);
    }

    private static void putL2(final SortedMap<String, String> fields, final L2MarketData l2) {
        put(fields, "order_book.ask_levels", l2.askSize);
        put(fields, "order_book.bid_levels", l2.bidSize);
        if (l2.askSize > 0) {
            put(fields, "order_book.ask_0.orders", l2.askOrders[0]);
            put(fields, "order_book.ask_0.price", l2.askPrices[0]);
            put(fields, "order_book.ask_0.volume", l2.askVolumes[0]);
        }
        if (l2.bidSize > 0) {
            put(fields, "order_book.bid_0.orders", l2.bidOrders[0]);
            put(fields, "order_book.bid_0.price", l2.bidPrices[0]);
            put(fields, "order_book.bid_0.volume", l2.bidVolumes[0]);
        }
    }

    private static void putUser(
            final SortedMap<String, String> fields,
            final String prefix,
            final SingleUserReportResult report,
            final long expectedOrderId) {

        put(fields, prefix + ".account.quote", report.getAccounts().get(QUOTE_CURRENCY));
        final SingleUserReportResult.Position position = report.getPositions().get(SYMBOL);
        assertNotNull(position, "missing " + prefix + " futures position");
        put(fields, prefix + ".position.direction", position.direction.name());
        put(fields, prefix + ".position.open_price_sum", position.openPriceSum);
        put(fields, prefix + ".position.open_volume", position.openVolume);
        put(fields, prefix + ".position.pending_buy", position.pendingBuySize);
        put(fields, prefix + ".position.pending_sell", position.pendingSellSize);
        put(fields, prefix + ".position.profit", position.profit);

        final Map<Long, Order> orders = report.fetchIndexedOrders();
        put(fields, prefix + ".orders.count", orders.size());
        final Order order = orders.get(expectedOrderId);
        if (order != null) {
            put(fields, prefix + ".order.action", order.action.name());
            put(fields, prefix + ".order.filled", order.filled);
            put(fields, prefix + ".order.id", order.orderId);
            put(fields, prefix + ".order.price", order.price);
            put(fields, prefix + ".order.reserve", order.reserveBidPrice);
            put(fields, prefix + ".order.size", order.size);
            put(fields, prefix + ".order.timestamp", order.timestamp);
        }
    }

    private static void put(final SortedMap<String, String> fields, final String key, final long value) {
        fields.put(key, Long.toString(value));
    }

    private static void put(final SortedMap<String, String> fields, final String key, final String value) {
        fields.put(key, quote(value));
    }

    private static List<String> sourceArtifactNames() {
        return Arrays.asList(
                snapshotFileName("ME", 0),
                snapshotFileName("RE", 0),
                journalFileName(SNAPSHOT_ID, 1));
    }

    private static String snapshotFileName(final String module, final int instance) {
        return EXCHANGE_ID + "_snapshot_" + SNAPSHOT_ID + "_" + module + instance + ".ecs";
    }

    private static String journalFileName(final long snapshotId, final int partition) {
        return String.format("%s_journal_%d_%04X.ecj", EXCHANGE_ID, snapshotId, partition);
    }

    private static void publishFixture(final GenerationResult generated, final Path targetRoot) throws Exception {
        Files.createDirectories(targetRoot);

        final List<ArtifactMetadata> artifacts = new ArrayList<>();
        for (String fileName : sourceArtifactNames()) {
            final Path source = generated.workDir.resolve(fileName);
            final Path target = targetRoot.resolve(fileName);
            publishOrCompare(source, target);
            artifacts.add(ArtifactMetadata.from(source, fileName));
        }

        final String manifest = manifestJson(generated, artifacts);
        final Path manifestPath = targetRoot.resolve("manifest.json");
        if (Files.exists(manifestPath)) {
            assertEquals(
                    manifest,
                    new String(Files.readAllBytes(manifestPath), StandardCharsets.UTF_8),
                    "manifest changed on fixture rerun");
        } else {
            Files.write(manifestPath, manifest.getBytes(StandardCharsets.UTF_8));
        }
    }

    private static void publishOrCompare(final Path source, final Path target) throws IOException {
        if (Files.exists(target)) {
            assertArrayEquals(
                    Files.readAllBytes(target),
                    Files.readAllBytes(source),
                    "existing fixture differs from regenerated bytes: " + target);
        } else {
            Files.copy(source, target, StandardCopyOption.COPY_ATTRIBUTES);
        }
    }

    private static String manifestJson(
            final GenerationResult generated,
            final List<ArtifactMetadata> artifacts) {

        final StringBuilder json = new StringBuilder();
        json.append("{\n")
                .append("  \"schemaVersion\": 1,\n")
                .append("  \"scenario\": \"disk-persistence-direct-1me-1re\",\n")
                .append("  \"generator\": \"exchange.core2.tests.fixtures.GenerateJavaPersistenceFixtureTest\",\n")
                .append("  \"exchangeId\": ").append(quote(EXCHANGE_ID)).append(",\n")
                .append("  \"snapshotId\": ").append(SNAPSHOT_ID).append(",\n")
                .append("  \"snapshotTimestampNs\": ").append(timestamp(20)).append(",\n")
                .append("  \"snapshotSequence\": {\"matching\": ")
                .append(generated.snapshotSequenceMatching)
                .append(", \"risk\": ")
                .append(generated.snapshotSequenceRisk)
                .append("},\n")
                .append("  \"journalMutations\": [")
                .append("{\"command\": \"BALANCE_ADJUSTMENT\", \"sequence\": ")
                .append(generated.journalBalanceSequence)
                .append(", \"timestampNs\": ").append(timestamp(22)).append("}, ")
                .append("{\"command\": \"PLACE_ORDER\", \"sequence\": ")
                .append(generated.journalOrderSequence)
                .append(", \"timestampNs\": ").append(timestamp(23)).append("}],\n")
                .append("  \"topology\": {\"matchingEngines\": 1, \"riskEngines\": 1, \"orderBook\": \"DIRECT\"},\n")
                .append("  \"persistence\": {\"processor\": \"DiskSerializationProcessor\", \"snapshotCompression\": \"LZ4_FAST_SAFE_JAVA\", \"journalEncoding\": \"RAW\", \"journalCompressionThreshold\": ")
                .append(JOURNAL_RAW_THRESHOLD).append("},\n")
                .append("  \"incompleteBinaryTransfer\": {\"transferId\": 0, \"wordsTransferred\": 5, \"lastFlag\": 0},\n")
                .append("  \"javaStateHash\": {\"recorded\": false, \"roundTripVerifiedInJvm\": true, \"reason\": \"JVM enum and object identity hashes are process-local\"},\n")
                .append("  \"excludedSourceFiles\": [{\"file\": ")
                .append(quote(EXCHANGE_ID + ".eca"))
                .append(", \"reason\": \"contains DiskSerializationProcessor wall-clock log metadata\"}],\n")
                .append("  \"artifacts\": [\n");

        for (int i = 0; i < artifacts.size(); i++) {
            final ArtifactMetadata artifact = artifacts.get(i);
            json.append("    {\"file\": ").append(quote(artifact.fileName))
                    .append(", \"length\": ").append(artifact.length)
                    .append(", \"sha256\": ").append(quote(artifact.sha256)).append("}");
            json.append(i + 1 == artifacts.size() ? "\n" : ",\n");
        }
        json.append("  ],\n")
                .append("  \"expected\": {\n")
                .append("    \"snapshot\": ").append(generated.snapshotState.toJson("    ")).append(",\n")
                .append("    \"afterJournalReplay\": ").append(generated.journalState.toJson("    ")).append("\n")
                .append("  }\n")
                .append("}\n");
        return json.toString();
    }

    private static String quote(final String value) {
        return "\"" + value
                .replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\n", "\\n") + "\"";
    }

    private static String sha256(final Path path) throws IOException, NoSuchAlgorithmException {
        final MessageDigest digest = MessageDigest.getInstance("SHA-256");
        final byte[] bytes = Files.readAllBytes(path);
        final byte[] hash = digest.digest(bytes);
        final StringBuilder hex = new StringBuilder(hash.length * 2);
        for (byte value : hash) {
            hex.append(String.format("%02x", value & 0xff));
        }
        return hex.toString();
    }

    private static void deleteWorkingDirectory(final Path directory) throws IOException {
        if (!Files.exists(directory)) {
            return;
        }
        try (DirectoryStream<Path> entries = Files.newDirectoryStream(directory)) {
            for (Path entry : entries) {
                Files.deleteIfExists(entry);
            }
        }
        Files.deleteIfExists(directory);
    }

    private static final class GenerationResult {
        private final Path workDir;
        private final long snapshotSequenceMatching;
        private final long snapshotSequenceRisk;
        private final long journalBalanceSequence;
        private final long journalOrderSequence;
        private final BusinessState snapshotState;
        private final BusinessState journalState;

        private GenerationResult(
                final Path workDir,
                final long snapshotSequenceMatching,
                final long snapshotSequenceRisk,
                final long journalBalanceSequence,
                final long journalOrderSequence,
                final BusinessState snapshotState,
                final BusinessState journalState) {
            this.workDir = workDir;
            this.snapshotSequenceMatching = snapshotSequenceMatching;
            this.snapshotSequenceRisk = snapshotSequenceRisk;
            this.journalBalanceSequence = journalBalanceSequence;
            this.journalOrderSequence = journalOrderSequence;
            this.snapshotState = snapshotState;
            this.journalState = journalState;
        }

        private void assertArtifactsExist() throws IOException {
            for (String fileName : sourceArtifactNames()) {
                final Path artifact = workDir.resolve(fileName);
                assertTrue(Files.isRegularFile(artifact), "missing generated artifact " + artifact);
                assertTrue(Files.size(artifact) > 0L, "generated artifact is empty " + artifact);
            }
        }
    }

    private static final class BusinessState {
        private final int javaStateHash;
        private final SortedMap<String, String> fields;

        private BusinessState(final int javaStateHash, final SortedMap<String, String> fields) {
            this.javaStateHash = javaStateHash;
            this.fields = fields;
        }

        private String toJson(final String indent) {
            final StringBuilder json = new StringBuilder();
            json.append("{\n");
            int index = 0;
            for (Map.Entry<String, String> field : fields.entrySet()) {
                json.append(indent).append("  ")
                        .append(quote(field.getKey()))
                        .append(": ")
                        .append(field.getValue());
                json.append(++index == fields.size() ? "\n" : ",\n");
            }
            json.append(indent).append("}");
            return json.toString();
        }

        @Override
        public boolean equals(final Object other) {
            if (this == other) {
                return true;
            }
            if (!(other instanceof BusinessState)) {
                return false;
            }
            final BusinessState that = (BusinessState) other;
            return javaStateHash == that.javaStateHash && fields.equals(that.fields);
        }

        @Override
        public int hashCode() {
            return 31 * javaStateHash + fields.hashCode();
        }

        @Override
        public String toString() {
            return "BusinessState{javaStateHash=" + javaStateHash + ", fields=" + fields + '}';
        }
    }

    private static final class ArtifactMetadata {
        private final String fileName;
        private final long length;
        private final String sha256;

        private ArtifactMetadata(final String fileName, final long length, final String sha256) {
            this.fileName = fileName;
            this.length = length;
            this.sha256 = sha256;
        }

        private static ArtifactMetadata from(final Path path, final String fileName) throws Exception {
            return new ArtifactMetadata(fileName, Files.size(path), sha256(path));
        }
    }
}
